import sys
import heapq

def main():
    import sys
    import heapq

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n, m = readints()
    adj = [[] for _ in range(n)]

    for _ in range(m):
        u, v = readints()
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    for i in range(n):
        adj[i].sort()

    visited = [False] * n
    pq = [(1, 0)]  # (node, parent)
    result = []

    while pq:
        node, parent = heapq.heappop(pq)
        if visited[node]:
            continue
        visited[node] = True
        result.append(node + 1)
        for neighbor in adj[node]:
            if not visited[neighbor]:
                heapq.heappush(pq, (neighbor, node))

    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
